exports.AccessibilityDeclarationSchema = {
    type: 'object',
    title: 'AccessibilityDeclaration',
    properties: {
        type: {
            type: 'string',
            enum: ['accessibilityDeclarations']
        },
        id: {
            type: 'string'
        },
        attributes: {
            type: 'object',
            properties: {
                deviceFamily: {
                    '$ref': '#/components/schemas/DeviceFamily'
                },
                state: {
                    type: 'string',
                    enum: ['DRAFT', 'PUBLISHED', 'REPLACED']
                },
                supportsAudioDescriptions: {
                    type: 'boolean'
                },
                supportsCaptions: {
                    type: 'boolean'
                },
                supportsDarkInterface: {
                    type: 'boolean'
                },
                supportsDifferentiateWithoutColorAlone: {
                    type: 'boolean'
                },
                supportsLargerText: {
                    type: 'boolean'
                },
                supportsReducedMotion: {
                    type: 'boolean'
                },
                supportsSufficientContrast: {
                    type: 'boolean'
                },
                supportsVoiceControl: {
                    type: 'boolean'
                },
                supportsVoiceover: {
                    type: 'boolean'
                }
            }
        },
        links: {
            '$ref': '#/components/schemas/ResourceLinks'
        }
    },
    required: ['id', 'type']
};
